$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$target = Join-Path $root "src\pages\Recipe.jsx"

if (-not (Test-Path $target)) {
    $nested = Join-Path $root "hankkiloop\src\pages\Recipe.jsx"
    if (Test-Path $nested) {
        $target = $nested
    } else {
        throw "Recipe.jsx를 찾지 못했습니다. hankkiloop 폴더 또는 프로젝트 루트에서 실행해주세요."
    }
}

$backup = "$target.bak-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
Copy-Item $target $backup

$base64 = @"

"@

$bytes = [Convert]::FromBase64String(($base64 -replace "\s",""))
[System.IO.File]::WriteAllBytes($target, $bytes)

Write-Host ""
Write-Host "Recipe.jsx 패치 완료" -ForegroundColor Green
Write-Host "대상: $target"
Write-Host "백업: $backup"
Write-Host ""
Write-Host "핵심 수정:"
Write-Host "- aiRecommendationIds가 비어 있으면 기존 recipes 전체를 표시"
Write-Host "- 추천 ID가 DB와 불일치해도 기존 recipes로 fallback"
Write-Host "- savedIds/listState 기본값 보강"
Write-Host "- 검색 시 undefined 필드 때문에 깨지지 않도록 방어"
Write-Host ""
Write-Host "이제 npm run build 또는 npm run dev로 확인하세요."
